INSERT INTO epr_antecedents (pseudonyme, atcd_perinataux, atcd_perinataux_precision, consanguinite_parentale, consanguinite_degre, atcd_familiaux_epilepsie, atcd_familiaux_lien, developpement_psychomoteur_avant_crises) VALUES ('EPR_MBH_001', TRUE, 'Grossesse gemellaire spontanee, cesarienne a 35 SA pour RCF pathologique (prematurite induite), Apgar 8-9-10, poids naissance 1700g, taille 46cm, PC 33cm, retard de croissance intra-uterin disharmonieux, hospitalisation 3 jours en neonatologie', FALSE, NULL, TRUE, 'Mere : crise epileptique en fin de grossesse sous Levetiracetam, sans recidive, bilan etiologique negatif. Frere jumeau EPR_MBH_002 suivi pour la meme encephalopathie epileptique genetique (mutation KCNQ2), decede en juin 2022. Autre frere de 7 ans en bonne sante apparente.', 'Retard');
INSERT INTO epr_antecedents (pseudonyme, atcd_perinataux, atcd_perinataux_precision, consanguinite_parentale, consanguinite_degre, atcd_familiaux_epilepsie, atcd_familiaux_lien, developpement_psychomoteur_avant_crises) VALUES ('EPR_MBH_002', TRUE, 'Grossesse gemellaire spontanee, cesarienne a 35 SA pour souffrance foetale aigue (RCF pathologique), Apgar 8-9-10, poids naissance 2420g, taille 47cm, PC 33cm, detresse respiratoire neonatale transitoire (CPAP 2 jours), osteomyelite du col femoral gauche traitee par antibiotherapie 60 jours + drainage chirurgical, pneumopathie a 11 mois', FALSE, NULL, TRUE, 'Mere : crise epileptique en cours de grossesse sous Levetiracetam, sans recidive, bilan etiologique negatif. Frere jumeau EPR_MBH_001 suivi pour la meme encephalopathie epileptique genetique (mutation KCNQ2). Autre frere de 7 ans en bonne sante apparente.', 'Retard');
INSERT INTO epr_antecedents (pseudonyme, atcd_perinataux, atcd_perinataux_precision, consanguinite_parentale, consanguinite_degre, atcd_familiaux_epilepsie, atcd_familiaux_lien, developpement_psychomoteur_avant_crises) VALUES ('EPR_MBH_005', FALSE, 'Cesarienne a terme pour uterus cicatriciel, pas de souffrance perinatale, poids naissance 3900g, pas de sejour en neonatologie', TRUE, 'Consanguinite parentale lointaine (grands-parents cousins de la meme region)', TRUE, 'Epilepsie et deficience intellectuelle, handicap moteur chez un cousin paternel (en rapport avec une souffrance perinatale) ; deficience intellectuelle et handicap moteur chez un autre cousin paternel ; 2 freres en bonne sante ; pas de deces en bas age dans la famille', 'Normal');
INSERT INTO epr_antecedents (pseudonyme, atcd_perinataux, atcd_perinataux_precision, consanguinite_parentale, consanguinite_degre, atcd_familiaux_epilepsie, atcd_familiaux_lien, developpement_psychomoteur_avant_crises) VALUES ('EPR_AZ_004', FALSE, 'Cesarienne a terme pour uterus cicatriciel, pas de souffrance perinatale, anemie ferriprive traitee', FALSE, NULL, FALSE, 'Pas d''antecedents familiaux d''epilepsie ou de maladie neurologique. Mere avec paralysie faciale peripherique droite en 2018. Soeur de 7 ans en bonne sante apparente.', 'Retard');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_001', '2020-01-15', 'Generalisee', 'Toniques neonatales, revulsion oculaire, cyanose faciale', 'Apyrexie (periode neonatale)');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_001', '2020-06-01', 'Generalisee', 'Myoclonies audiogenes, spasmes en flexion, clonies palpebrales, crises hypertoniques', 'Episodes grippaux, poussees dentaires');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_002', '2020-01-15', 'Generalisee', 'Crises toniques neonatales, revulsion oculaire, cyanose faciale', 'Apyrexie (periode neonatale)');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_002', '2022-05-07', 'Focale a bilateralisation', 'Crises toniques asymetriques a predominance gauche, myoclonies audiogenes, etat de mal epileptique', 'Arret du Levetiracetam par la famille');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_005', '2020-01-01', 'Focale', 'Rupture de conscience breve avec hypotonie des 4 membres et confusion post-critique', 'Aucun identifie (apyrexie)');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_MBH_005', '2024-11-01', 'Focale avec alteration de conscience', 'Aura non exprimee, automatismes gestuels (recherche d''un lieu securise), ecartement/rapprochement des genoux, hypertonie des 4 membres, rires gelastiques, fixite du regard, crampes post-critiques (60-90 secondes)', NULL);
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_AZ_004', '2019-08-01', 'Generalisee', 'Perte de connaissance breve avec resolution du tonus, sans hypertonie ni revulsion oculaire', 'Apyrexie');
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_AZ_004', '2020-02-01', 'Generalisee', 'Crises toniques generalisees avec fixite du regard et hypertonie des 4 membres', NULL);
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_AZ_004', '2022-06-20', 'Generalisee', 'Crises atoniques et probables myoclono-atoniques (lachage d''objets)', NULL);
INSERT INTO epr_type_crise (pseudonyme, date_observation, type_crise_ilae2017, sous_type, facteurs_declenchants) VALUES ('EPR_AZ_004', '2023-07-18', 'Focale a bilateralisation possible', 'Chute de la tete, vocalisation, hoquet', 'Inobservance therapeutique (arret 2 jours)');
