INSERT INTO epr_examen (pseudonyme, date_examen, neuro_eveil_reactivite, neuro_langage, neuro_comportement, neuro_marche, neuro_station_debout, neuro_tonus, neuro_force_motrice, neuro_reflexes, neuro_mouvements_anormaux, poids_kg, taille_cm, perimetre_cranien_cm, lesions_cutanees, deformations_osseuses, dysmorphie_faciale) VALUES ('EPR_MBH_001', '2020-01-15', 'Reagit aux stimuli sonores, Glasgow 15/15', 'Retard severe du langage', 'Mauvais contact social', 'Non acquise', 'Non acquise, hypotonie axiale, tenue de tete impossible', 'Hypotonie axiale et segmentaire, exageration du ballant des membres inferieurs', NULL, 'ROT vifs diffuses aux membres inferieurs, RCP indifferent', 'Nystagmus horizontal bilateral, attitude en batracien, mauvaise poursuite oculaire', 8, 80, 46, NULL, 'Scoliose dorsolombaire, chevauchement du 2e orteil bilateral, hypertrophie gingivale', 'Presente (non detaillee)');
INSERT INTO epr_examen (pseudonyme, date_examen, neuro_eveil_reactivite, neuro_langage, neuro_comportement, neuro_marche, neuro_station_debout, neuro_tonus, neuro_force_motrice, neuro_reflexes, neuro_mouvements_anormaux, poids_kg, taille_cm, perimetre_cranien_cm, lesions_cutanees, deformations_osseuses, dysmorphie_faciale) VALUES ('EPR_MBH_002', '2020-01-15', 'Reagit aux stimuli sonores, Glasgow 15/15', 'Retard severe du langage', 'Mauvais contact social', 'Non acquise', 'Non acquise, hypotonie axiale, tenue de tete impossible', 'Hypotonie axiale et segmentaire, exageration du ballant des membres inferieurs', NULL, 'ROT vifs diffuses aux membres inferieurs, signe de Rossolimo present, RCP en flexion', 'Nystagmus horizontal, open jaw dystonia, attitude en batracien', 8, 76, 47, 'Hypertrophie gingivale, cicatrice chirurgicale hanche gauche', 'Scoliose dorsolombaire, limitation de la rotation externe de hanche gauche, chevauchement du 2e orteil bilateral', NULL);
INSERT INTO epr_examen (pseudonyme, date_examen, neuro_eveil_reactivite, neuro_langage, neuro_comportement, neuro_marche, neuro_station_debout, neuro_tonus, neuro_force_motrice, neuro_reflexes, neuro_mouvements_anormaux, poids_kg, taille_cm, perimetre_cranien_cm, lesions_cutanees, deformations_osseuses, dysmorphie_faciale) VALUES ('EPR_MBH_005', '2024-11-01', 'Correct', 'Langage enfantin limite a des phrases simples (forte presomption de deficience intellectuelle)', 'Pas de trouble du comportement objective, pas d''hyperactivite', 'Autonome et stable', 'Stable', 'Normal', 'Pas de deficit moteur', 'Presents et symetriques, pas de trouble de la coordination', 'Aucun, examen des paires craniennes normal', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO epr_examen (pseudonyme, date_examen, neuro_eveil_reactivite, neuro_langage, neuro_comportement, neuro_marche, neuro_station_debout, neuro_tonus, neuro_force_motrice, neuro_reflexes, neuro_mouvements_anormaux, poids_kg, taille_cm, perimetre_cranien_cm, lesions_cutanees, deformations_osseuses, dysmorphie_faciale) VALUES ('EPR_AZ_004', '2023-07-18', 'Bien oriente, conscient', NULL, 'Deficience intellectuelle, pas de trouble du comportement ni hyperactivite', 'Autonome, stable (marche sur talons, pointes de pied, en tandem)', 'Stable, pas de signe de Romberg', 'Normal', 'Pas de deficit moteur (Barre et Mingazzini negatifs)', 'ROT presents et symetriques, RCP en flexion, pas de signe de Hoffman ni de Rossolimo', 'Aucun', 55, NULL, NULL, 'Pas de taches cafe au lait', NULL, 'Absente');
