INSERT INTO epr_etiologie (pseudonyme, categorie_etiologique, etiologie_principale, detail_lesion_structurelle, detail_gene_mute, detail_maladie_metabolique, detail_facteur_infectieux, detail_maladie_auto_immune) VALUES ('EPR_AZ_004', 'Genetique', FALSE, NULL, 'Genes evoques : GRIN2A (POCS) ; SCN1A, SCN1B, SCN2A, STX1B, SCN6A1, CHD2 (epilepsie myoclono-atonique) ; SLC2A1/GLUT1 ; caryotype et etude genique complementaire proposes, resultats non retrouves dans le dossier', NULL, NULL, NULL);
