INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Valproate de sodium (Depakine)', '50 mg x2/j puis 200 mg x2/j (~30 mg/kg/j)', 'Depuis l''age de 3 mois, en cours', 'Reduction partielle de la frequence des crises', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Clonazepam (Rivotril)', '1 mg/j puis doses variables (1/4 cp x2)', 'Depuis l''age de 3 mois, avec interruptions', 'Reponse partielle', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Phenytoine (Dilantin)', '15 mg/j (5 mg/kg/j)', 'Environ 3-4 mois', 'Amelioration initiale puis arrete', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Prednisolone (Solupred)', 'Non precisee', '2 mois (introduit a 4 mois)', 'Pas d''amelioration', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Hydrocortisone (Cortef)', 'Non precisee', '14 semaines (introduit a 9 mois)', 'Pas d''amelioration', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Levetiracetam (Levet)', '2 ml x2/j (~50-60 mg/kg/j)', 'Plusieurs annees, arrete en 2023 par la mere', 'Inefficacite percue par la famille, non-observance', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Clobazam (Urbanyl)', '1/4 cp x2/j (~0,625 mg/kg/j)', 'Plusieurs mois, remplace par le Rivotril', 'Peu efficace', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Carbamazepine (Tegretol) - 1er essai', '50 mg x2 puis 100 mg x2/j', 'Environ 1 semaine (octobre 2023)', 'Aggravation des crises', 'Effet indesirable');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_001', 'Carbamazepine (Tegretol/Taver) - reintroduction', '15 mg/kg/j, doses progressives', 'Depuis 2024, en cours', 'Amelioration nette, 0 crise/jour, epilepsie bien equilibree', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Valproate de sodium (Depakine)', '50 mg x2/j puis 200 mg x2/j', 'Depuis l''age de 3 mois, en cours', 'Reponse partielle', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Phenytoine (Dilantin)', '15 mg/j (5 mg/kg/j)', 'Environ 3 mois', 'Amelioration initiale', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Clonazepam (Rivotril)', '1 mg/j puis 1/4 cp x2', 'Depuis l''age de 3 mois, en cours', 'Reponse partielle', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Prednisolone (Solupred)', 'Non precisee', '2 semaines (2018)', 'Pas d''amelioration', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Hydrocortisone (Cortef)', 'Non precisee', '50 jours (2019)', 'Pas d''amelioration', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Clobazam (Urbanyl)', '1/4 cp/j (0,625 mg/kg/j)', 'Plusieurs mois', 'Reponse partielle', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Levetiracetam (Levet)', '2 ml x2/j', 'Arrete par la famille avant mai 2022', 'Identifie comme facteur decompensant a l''arret', 'Inefficacite / non-observance');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Phenytoine (protocole aigu)', '15 mg/kg puis 5 mg/kg toutes les 6h', 'Mai 2022 (etat de mal)', 'Pas de recidive sous surveillance', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_002', 'Lamotrigine (Lamictal)', 'Introduction progressive, mai 2022', 'Introduit a la sortie d''hospitalisation', 'Non evalue (fin du dossier)', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Valproate de sodium (Depakine sirop puis chrono)', 'Doses variables', 'Environ 1 an', 'Sans amelioration de la frequence des crises', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Carbamazepine (Tegretol)', 'Non precisee', '3 mois', 'Inefficace', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Association Lamictal + Levet + Urbanyl', 'Non precisee', 'Non precisee', 'Eruption cutanee, cytolyse hepatique, fievre (arret de tous les traitements)', 'Effet indesirable');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Clobazam (Aklonil)', '1/2 comprime par jour', 'Introduit fin 2022', 'Diminution initiale des crises puis echappement apres quelques semaines', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Association Aklonil + Lamictal + Trileptal (oxcarbazepine)', 'Non precisee', 'Fin 2022', 'Sans amelioration, 3 crises/jour', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Clonazepam (Rivotril) a hautes doses', '1 - 1/2 - 1 comprime', 'Environ 1 mois', 'Bonne reponse initiale, libre de crises 1 mois, rechute apres infection bronchique', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Topiramate (Epitomax)', 'Non precisee', 'Non precisee', 'Hallucinations visuelles, agitation psychomotrice ayant motive l''arret', 'Effet indesirable');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Lamotrigine (Lamictal) - reprise', '75 mg x2/j (6 mg/kg/j)', 'En cours en 2024-2025', 'Amelioration progressive de la frequence des crises', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_MBH_005', 'Clobazam (Urbanyl) - association actuelle', '1/2 cp x2/j', 'En cours en 2024-2025', 'Association au Lamictal, poursuite du traitement', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Valproate de sodium (Depakine sirop puis Chrono)', '350 mg x2/j (23 mg/kg/j) puis 500 mg x2/j (28 mg/kg/j), doses ajustees', 'Depuis fevrier 2020, en cours', 'Reponse partielle, dosages plasmatiques difficiles a equilibrer', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Clobazam (Urbanyl)', '1/2 cp/j a 1 cp x2/j selon les periodes, arrets intermittents', 'Depuis janvier 2021, de facon intermittente', 'Reponse partielle, aggravations rapportees a l''arret', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Lamotrigine (Lamictal)', 'Progressive de 25 mg/j a 3 cp x2/j (~4,4 mg/kg/j)', 'Depuis fevrier 2021, en cours', 'Diminution de la frequence des crises, bonne tolerance', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Clonazepam (Rivotril)', '1/4 cp x2/j', 'Introduit en 2025', 'En cours d''evaluation', NULL);
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Levetiracetam (Levet/Lepix puis Epilepta)', '500 mg, doses croissantes', 'Introduit en 2025, switche en 2026 (rupture de stock)', 'Sans amelioration nette, reduit puis change pour probleme de disponibilite', 'Inefficacite');
INSERT INTO epr_liste_ae (pseudonyme, nom_ae, dose, duree, reponse, motif_echec) VALUES ('EPR_AZ_004', 'Topiramate (Epitomax)', 'Non precisee', 'Non obtenue (2026)', 'Non evalue, rupture d''approvisionnement', NULL);
