INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_MBH_002', '2020-02-20', 'Anormal', 'Anomalies intercritiques, rythme de fond accelere pour l''age', 'Predominance frontale droite', FALSE, NULL, NULL);
INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_MBH_005', '2020-09-03', 'Anormal', 'Decharges epileptiques a l''endormissement', 'Fronto-temporal, predominance gauche', FALSE, NULL, NULL);
INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_AZ_004', '2020-02-28', 'Anormal', 'Rythme de fond ralenti, anomalies paroxystiques generalisees', 'Generalise', TRUE, '2020-02-28', 'Crise tonique generalisee');
INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_AZ_004', '2022-02-01', 'Anormal', 'Pattern de pointes-ondes continues du sommeil (POCS) suspecte ; compte-rendu et trace non disponibles', NULL, FALSE, NULL, NULL);
INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_AZ_004', '2023-04-19', 'Anormal', 'POCS en sommeil ; anomalies centro-temporales bilaterales en veille', 'Centro-temporal bilateral', FALSE, NULL, NULL);
INSERT INTO epr_eeg (pseudonyme, date_eeg, eeg_intercritique, type_anomalie, localisation_foyer, eeg_video_realise, date_eeg_video, type_crise_enregistree) VALUES ('EPR_AZ_004', '2023-07-22', 'Anormal', 'Pointes-ondes generalisees s''organisant en bouffees, pas d''aspect de POCS', 'Generalise', FALSE, NULL, NULL);
